mapper.sql:
and (
    exists (
        select 1 from exam_user access_eu
        where access_eu.exam_id = e.id
          and access_eu.user_id = #{params.userId}
    )
    or exists (
        select 1
        from exam_examination_dept access_ed
        left join sys_dept access_d on access_d.dept_id = #{params.deptId}
        where access_ed.exam_id = e.id
          and (
              access_ed.dept_id = #{params.deptId}
              or (access_ed.include_children = '1'
                  and access_d.ancestors is not null
                  and find_in_set(access_ed.dept_id, access_d.ancestors))
          )
    )
    or (
        not exists (select 1 from exam_user any_eu where any_eu.exam_id = e.id)
        and not exists (select 1 from exam_examination_dept any_ed where any_ed.exam_id = e.id)
    )
)

