        and date_format(e.start_time,'%y%m%d') >= date_format(#{params.beginTime},'%y%m%d')


        and date_format(e.end_time,'%y%m%d') <= date_format(#{params.endTime},'%y%m%d')





order by

    case
        when e.start_time <= now() and e.end_time > now() then 1  -- 进行中
        when e.start_time > now() then 2  -- 未开始
        else 3  -- 已结束
    end,

    case when e.start_time <= now() and e.end_time > now() then e.end_time end asc,

    case when e.start_time > now() then e.start_time end asc,

    case when e.end_time <= now() then e.end_time end desc

select count(1)
from exam_examination e
where e.id = #{examId}
  and (
      exists (
          select 1 from exam_user eu
          where eu.exam_id = e.id
            and eu.user_id = #{userId}
      )
      or exists (
          select 1
          from exam_examination_dept ed
          left join sys_dept d on d.dept_id = #{deptId}
          where ed.exam_id = e.id
            and (
                ed.dept_id = #{deptId}
                or (ed.include_children = '1'
                    and d.ancestors is not null
                    and find_in_set(ed.dept_id, d.ancestors))
            )
      )
      or (
          not exists (select 1 from exam_user any_eu where any_eu.exam_id = e.id)
